import System.Collections.Generic.*
import System.Linq.*
public class Check {
    public static func Run() -> int {
        let values: int[] = [1, 22]
        let view: IList<int> = values
        view[0] = 20
        if values[0] != 20 { return 1 }
        let selected = values.Where(value => value > 0).ToArray()
        return selected[0] + selected[1]
    }
}
func Main() -> int { return Check.Run() }
